package com.dy.artisan3d.ui.themeimport androidx.compose.animation.animateColorAsStateimport androidx.compose.foundation.isSystemInDarkThemeimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.darkColorSchemeimport androidx.compose.material3.lightColorSchemeimport androidx.compose.runtime.Composableimport androidx.compose.runtime.getValueimport androidx.compose.ui.graphics.Colorimport com.dy.artisan3d.isAndroidPlatformimport com.dy.artisan3d.util.PlatformSystemBars// ── Primary (Terrakota) ──────────────────────val Primary = Color(0xFFC2622A)val OnPrimary = Color(0xFFFFFFFF)val PrimaryContainer = Color(0xFFFBD9C6)val OnPrimaryContainer = Color(0xFF3D1100)// ── Secondary (Loy jigarrang) ─────────────────val Secondary = Color(0xFF7C5C3E)val OnSecondary = Color(0xFFFFFFFF)val SecondaryContainer = Color(0xFFEFD9C4)val OnSecondaryContainer = Color(0xFF2C1500)// ── Tertiary (Rishton ko'k-yashil naqsh) ──────val Tertiary = Color(0xFF5B6B38)val OnTertiary = Color(0xFFFFFFFF)val TertiaryContainer = Color(0xFFD3E8C8)val OnTertiaryContainer = Color(0xFF1A2F08)// ── Error ────────────────────────────────────val Error = Color(0xFFBA1A1A)val OnError = Color(0xFFFFFFFF)val ErrorContainer = Color(0xFFFFDAD6)val OnErrorContainer = Color(0xFF410002)// ── Surface / Background (Light) ─────────────val Background = Color(0xFFFFF8F3)val OnBackground = Color(0xFF1C0800)val Surface = Color(0xFFFFF8F3)val OnSurface = Color(0xFF1C0800)val SurfaceVariant = Color(0xFFF5EDDE)val OnSurfaceVariant = Color(0xFF52382A)val Outline = Color(0xFF9E8775)val OutlineVariant = Color(0xFFD4C4B4)// ── Dark theme tokens ─────────────────────────val PrimaryDark = Color(0xFFFFB58A)val OnPrimaryDark = Color(0xFF5A1E00)val PrimaryContainerDark = Color(0xFF8C3A10)val OnPrimaryContainerDark = Color(0xFFFBD9C6)val SecondaryDark = Color(0xFFD4B99A)val OnSecondaryDark = Color(0xFF442B14)val SecondaryContainerDark = Color(0xFF624528)val OnSecondaryContainerDark = Color(0xFFEFD9C4)val TertiaryDark = Color(0xFFBDCA8D)val OnTertiaryDark = Color(0xFF2C3A0D)val TertiaryContainerDark = Color(0xFF435222)val OnTertiaryContainerDark = Color(0xFFD3E8C8)val ErrorDark = Color(0xFFFFB4AB)val OnErrorDark = Color(0xFF690005)val ErrorContainerDark = Color(0xFF93000A)val OnErrorContainerDark = Color(0xFFFFDAD6)val BackgroundDark = Color(0xFF1C1008)val OnBackgroundDark = Color(0xFFF5DEC8)val SurfaceDark = Color(0xFF1C1008)val OnSurfaceDark = Color(0xFFF5DEC8)val SurfaceVariantDark = Color(0xFF2E1A0B)val OnSurfaceVariantDark = Color(0xFFD4C4B4)val OutlineDark = Color(0xFF6B5040)val OutlineVariantDark = Color(0xFF52382A)val LightColorScheme = lightColorScheme(    primary = Primary,    onPrimary = OnPrimary,    primaryContainer = PrimaryContainer,    onPrimaryContainer = OnPrimaryContainer,    secondary = Secondary,    onSecondary = OnSecondary,    secondaryContainer = SecondaryContainer,    onSecondaryContainer = OnSecondaryContainer,    tertiary = Tertiary,    onTertiary = OnTertiary,    tertiaryContainer = TertiaryContainer,    onTertiaryContainer = OnTertiaryContainer,    error = Error,    onError = OnError,    errorContainer = ErrorContainer,    onErrorContainer = OnErrorContainer,    background = Background,    onBackground = OnBackground,    surface = Surface,    onSurface = OnSurface,    surfaceVariant = SurfaceVariant,    onSurfaceVariant = OnSurfaceVariant,    outline = Outline,    outlineVariant = OutlineVariant,)val DarkColorScheme = darkColorScheme(    primary = PrimaryDark,    onPrimary = OnPrimaryDark,    primaryContainer = PrimaryContainerDark,    onPrimaryContainer = OnPrimaryContainerDark,    secondary = SecondaryDark,    onSecondary = OnSecondaryDark,    secondaryContainer = SecondaryContainerDark,    onSecondaryContainer = OnSecondaryContainerDark,    tertiary = TertiaryDark,    onTertiary = OnTertiaryDark,    tertiaryContainer = TertiaryContainerDark,    onTertiaryContainer = OnTertiaryContainerDark,    error = ErrorDark,    background = BackgroundDark,    onBackground = OnBackgroundDark,    surface = SurfaceDark,    onSurface = OnSurfaceDark,    surfaceVariant = SurfaceVariantDark,    onSurfaceVariant = OnSurfaceVariantDark,    outline = OutlineDark,    outlineVariant = OutlineVariantDark,    onError = OnErrorDark,    onErrorContainer = OnErrorContainerDark,    errorContainer = ErrorContainerDark,)@Composablefun Artisan3DTheme(    darkTheme: Boolean = isSystemInDarkTheme(),    content: @Composable () -> Unit,) {    val targetColorScheme = if (darkTheme) DarkColorScheme else LightColorScheme    val animatedBackground by animateColorAsState(targetColorScheme.background)    val animatedSurface by animateColorAsState(targetColorScheme.surface)    val colorScheme = targetColorScheme.copy(        background = animatedBackground,        surface = animatedSurface    )    PlatformSystemBars(darkTheme)    MaterialTheme(        colorScheme = colorScheme,        typography = MaterialTheme.typography,        content = content    )}